cands = []
for bias in (0.80, 0.75):
    for yf in (1951, 1960, 1970):
        cands.append({"stat":"median","form":"mult","W":3,"decay":0.7,"shrink":0.2,"bias":bias,"year_from":yf})
        for W in (4,6):
            for d in (0.7,0.8):
                cands.append({"stat":"median","form":"mult","W":W,"decay":d,"shrink":0.2,"bias":bias,"year_from":yf})
import json, re
p = 'solution/seasonal_bias_probe.py'
src = open(p).read()
block = "[\n" + ",\n".join("    " + json.dumps(c, ensure_ascii=False) for c in cands) + ",\n]"
src = re.sub(r"candidates = \[.*?\]", block, src, count=1, flags=re.S)
open(p,'w').write(src)
print(len(cands), "candidates")
PY"}

