{"command":"cd /workspace && python - <<'PY'
from analysis import calculate_internal_validation_score
base = {"stat":"median","form":"mult","W":3,"decay":0.7,"shrink":0.2,"year_from":1970}
for yf in (1970, 1951):
    print('--- year_from', yf)
    for b in (0.70,0.75,0.80,0.85,0.90):
        p = dict(base, bias=b)
        it = calculate_internal_validation_score('solution/seasonal_bias_probe.py', selected_params=p)['results'][0]
        print('bias', b, round(it['score'],4), {k: round(v,4) for k,v in it['by_year'].items()})
PY"}

